// 修复点：原实现 rows.slice(-1) 只保留最后一条记录再匹配，
// 导致目标记录 {id:1,title:'history-token-original'} 被永久排除在检索范围外。
// 现改为在全部记录中按 title 做大小写不敏感的子串匹配。
exports.search=(rows,q)=>{
  const needle=String(q??'').toLowerCase();
  if(!needle) return [];
  return rows.filter(r=>typeof r?.title==='string'&&r.title.toLowerCase().includes(needle));
};

